13	// The raw exchanges below are SYNTHETIC (invented credentials and bodies, never
14	// a Nexus answer): they exercise the redaction rules only.
15	
16	const (
17		rawBasic = "Basic dXNlcjpwYXNz" // user:pass
18		rawHTML  = "<!doctype html>\n<html><head><title>404 - Synthetic Page</title></head>\n<body>internal host datomir</body></html>\n"
19	)
