21	func rawHeader(kv ...string) http.Header {
22		h := http.Header{}
23		for i := 0; i+1 < len(kv); i += 2 {
24			h.Add(kv[i], kv[i+1])
25		}
26		return h
27	}
28	
29	func rawJSONExchange(body string) nexusfixture.RawExchange {
30		return nexusfixture.RawExchange{
31			Method: "GET", Target: "/service/rest/v1/repositories/docker-proxy", Host: "127.0.0.1:30481",
32			RequestHeader: rawHeader("Authorization", rawBasic, "Accept", "application/json"),
33			Status:        200,
34			Header:        rawHeader("Server", "Nexus/3.98.1-01 (COMMUNITY)", "Content-Type", "application/json"),
35			Body:          []byte(body),
36		}
37	}
