39	func TestResponseHeaderAllowlistIsTheClosedList(t *testing.T) {
40		want := []string{"Server", "Content-Type", "Content-Length", "Docker-Distribution-Api-Version",
41			"Docker-Content-Digest", "Link", "WWW-Authenticate", "Location"}
42		got := slices.Clone(nexusfixture.ResponseHeaderAllowlist)
43		slices.Sort(got)
44		slices.Sort(want)
45		if !slices.Equal(got, want) {
46			t.Errorf("ResponseHeaderAllowlist = %v, want exactly %v", got, want)
47		}
48	}
