50	func TestRedactKeepsTheRequestLine(t *testing.T) {
51		ex := nexusfixture.Redact(rawJSONExchange(`{"name" : "docker-proxy"}`))
52		if ex.Method != "GET" || ex.Target != "/service/rest/v1/repositories/docker-proxy" || ex.Host != "127.0.0.1:30481" {
53			t.Errorf("request line = %s %s (Host %s), want it passed through", ex.Method, ex.Target, ex.Host)
54		}
55		if ex.Status != 200 {
56			t.Errorf("Status = %d, want 200", ex.Status)
57		}
58		if ex.Header.Get("Host") != "" || ex.RequestHeader.Get("Host") != "" {
59			t.Errorf("Host is Exchange.Host only, not a header (%v / %v)", ex.RequestHeader, ex.Header)
60		}
61	}
