63	func TestRedactAuthorization(t *testing.T) {
64		cases := []struct {
65			name, value string
66			want        string // "" = the header must be gone or carry no part of the value
67		}{
68			{"basic", rawBasic, "Basic <redacted>"},
69			{"basic lowercase scheme", "basic dXNlcjpwYXNz", "Basic <redacted>"},
70			{"bearer", "Bearer s3cr3t-opaque-token", "Bearer <redacted>"},
71			{"already placeholder", "Basic <redacted>", "Basic <redacted>"},
72			{"unknown scheme", "Digest username=\"bob\", response=\"abcdef\"", ""},
73		}
74		for _, tc := range cases {
75			t.Run(tc.name, func(t *testing.T) {
76				raw := rawJSONExchange(`{}`)
77				raw.RequestHeader = rawHeader("Authorization", tc.value)
78				ex := nexusfixture.Redact(raw)
79				got := ex.RequestHeader.Get("Authorization")
80				if tc.want != "" && got != tc.want {
81					t.Errorf("Authorization = %q, want %q", got, tc.want)
82				}
83				if tc.want == "" && got != "" && got != "Basic <redacted>" && got != "Bearer <redacted>" {
84					t.Errorf("Authorization = %q, want it absent or a placeholder", got)
85				}
86				for _, secret := range []string{"dXNlcjpwYXNz", "s3cr3t-opaque-token", "abcdef", "bob"} {
87					if strings.Contains(strings.Join(ex.RequestHeader.Values("Authorization"), "|"), secret) {
88						t.Errorf("Authorization %v still carries %q", ex.RequestHeader.Values("Authorization"), secret)
89					}
90				}
91			})
92		}
93	}
