95	func TestRedactRequestHeaders(t *testing.T) {
96		raw := rawJSONExchange(`{}`)
97		raw.RequestHeader = rawHeader(
98			"Authorization", rawBasic,
99			"Accept", "application/json",
100			"Cookie", "NXSESSIONID=abc123",
101			"X-Nexus-UI", "true",
102		)
103		ex := nexusfixture.Redact(raw)
104		if got := ex.RequestHeader.Get("Accept"); got != "application/json" {
105			t.Errorf("Accept = %q, want it kept as sent", got)
106		}
107		for _, name := range []string{"Cookie", "X-Nexus-UI"} {
108			if v := ex.RequestHeader.Values(name); len(v) != 0 {
109				t.Errorf("request header %s = %v, want it dropped", name, v)
110			}
111		}
112	}
