114	func TestRedactResponseHeadersKeepOnlyTheAllowlist(t *testing.T) {
115		raw := rawJSONExchange(`{"repositories":[]}`)
116		raw.Header = rawHeader(
117			"Server", "Nexus/3.98.1-01 (COMMUNITY)",
118			"Content-Type", "application/json",
119			"Content-Length", "19",
120			"Docker-Distribution-Api-Version", "registry/2.0",
121			"Docker-Content-Digest", "sha256:0000",
122			"Link", `</v2/_catalog?last=a&n=1>; rel="next"`,
123			"WWW-Authenticate", `Bearer realm="http://127.0.0.1:30481/v2/token"`,
124			"Location", "http://127.0.0.1:30481/elsewhere",
125			"Set-Cookie", "NXSESSIONID=abc123; Path=/",
126			"X-Foo", "bar",
127			"Date", "Tue, 17 Nov 2026 10:00:00 GMT",
128			"X-Content-Type-Options", "nosniff",
129		)
130		ex := nexusfixture.Redact(raw)
131		for _, name := range nexusfixture.ResponseHeaderAllowlist {
132			want := raw.Header.Values(name)
133			if got := ex.Header.Values(name); !slices.Equal(got, want) {
134				t.Errorf("response header %s = %v, want %v (kept as sent)", name, got, want)
135			}
136		}
137		for name := range ex.Header {
138			if !slices.ContainsFunc(nexusfixture.ResponseHeaderAllowlist, func(a string) bool { return http.CanonicalHeaderKey(a) == name }) {
139				t.Errorf("response header %s survived, it is not in the allowlist", name)
140			}
141		}
142	}
