144	func TestRedactDoesNotModifyItsInput(t *testing.T) {
145		raw := rawJSONExchange(`{"token" : "abc"}`)
146		raw.RequestHeader.Set("Cookie", "NXSESSIONID=abc")
147		raw.Header.Set("Set-Cookie", "NXSESSIONID=abc")
148		_ = nexusfixture.Redact(raw)
149		if raw.RequestHeader.Get("Authorization") != rawBasic || raw.RequestHeader.Get("Cookie") == "" {
150			t.Errorf("request headers of the input changed: %v", raw.RequestHeader)
151		}
152		if raw.Header.Get("Set-Cookie") == "" {
153			t.Errorf("response headers of the input changed: %v", raw.Header)
154		}
155		if string(raw.Body) != `{"token" : "abc"}` {
156			t.Errorf("body of the input changed: %q", raw.Body)
157		}
158	}
