160	func TestRedactBodies(t *testing.T) {
161		htmlRaw := rawJSONExchange("")
162		htmlRaw.Status = 404
163		htmlRaw.Header = rawHeader("Server", "Nexus/3.98.1-01 (COMMUNITY)", "Content-Type", "text/html;charset=utf-8", "Content-Length", "109")
164		htmlRaw.Body = []byte(rawHTML)
165	
166		emptyRaw := rawJSONExchange("")
167		emptyRaw.Status = 403
168		emptyRaw.Body = nil
169	
170		jsonRaw := rawJSONExchange(`{"repositories":["api","team/api"]}`)
171	
172		t.Run("HTML is summarised with its size and title", func(t *testing.T) {
173			ex := nexusfixture.Redact(htmlRaw)
174			want := "<HTML body omitted: " + itoa(len(rawHTML)) + " bytes, <title>404 - Synthetic Page</title>>"
175			if ex.Stub != want {
176				t.Errorf("Stub = %q, want %q", ex.Stub, want)
177			}
178			if ex.Body != nil {
179				t.Errorf("Body = %q, want nil when Stub is set", ex.Body)
180			}
181		})
182		t.Run("an empty body reads <empty body>", func(t *testing.T) {
183			ex := nexusfixture.Redact(emptyRaw)
184			if ex.Stub != "<empty body>" || ex.Body != nil {
185				t.Errorf("Stub = %q, Body = %q, want <empty body> and nil", ex.Stub, ex.Body)
186			}
187		})
188		t.Run("a JSON body is kept verbatim", func(t *testing.T) {
189			ex := nexusfixture.Redact(jsonRaw)
190			if ex.Stub != "" || string(ex.Body) != `{"repositories":["api","team/api"]}` {
191				t.Errorf("Stub = %q, Body = %q, want the body untouched", ex.Stub, ex.Body)
192			}
193		})
194	}
