196	func TestRedactSecretJSONValues(t *testing.T) {
197		cases := []struct{ name, in, want string }{
198			{
199				"uploaderIp spaced like Nexus writes it",
200				`{ "name" : "x", "uploaderIp" : "10.1.2.3" }`,
201				`{ "name" : "x", "uploaderIp" : "<redacted>" }`,
202			},
203			{
204				"compact",
205				`{"token":"abc","access_token":"def","refresh_token":"ghi"}`,
206				`{"token":"<redacted>","access_token":"<redacted>","refresh_token":"<redacted>"}`,
207			},
208			{
209				"password and secret, nested",
210				`{"a":{"password": "p","b":[{"secret":"s"}]}}`,
211				`{"a":{"password": "<redacted>","b":[{"secret":"<redacted>"}]}}`,
212			},
213			{
214				"a value with an escaped quote is replaced whole",
215				`{"password":"p\"q\\","x":"y"}`,
216				`{"password":"<redacted>","x":"y"}`,
217			},
218			{
219				"every other byte stays: escapes, unicode, layout",
220				"{\n  \"name\" : \"caf\\u00e9 \\/ \u00e9\",\n  \"token\" : \"abc\",\n  \"n\" : 1.50\n}",
221				"{\n  \"name\" : \"caf\\u00e9 \\/ \u00e9\",\n  \"token\" : \"<redacted>\",\n  \"n\" : 1.50\n}",
222			},
223			{
224				"other keys and words in values are left alone",
225				`{"username" : "admin", "message" : "no token here", "tokenType" : "keep"}`,
226				`{"username" : "admin", "message" : "no token here", "tokenType" : "keep"}`,
227			},
228			{
229				"an already redacted value is stable",
230				`{"token" : "<redacted>"}`,
231				`{"token" : "<redacted>"}`,
232			},
233		}
234		for _, tc := range cases {
235			t.Run(tc.name, func(t *testing.T) {
236				ex := nexusfixture.Redact(rawJSONExchange(tc.in))
237				if string(ex.Body) != tc.want {
238					t.Errorf("Body =\n%s\nwant\n%s", ex.Body, tc.want)
239				}
240			})
241		}
242	}
