244	// TestRedactThenCheckIsClean is the contract between the recorder's two steps:
245	// whatever Redact writes, CheckLeaks accepts.
246	func TestRedactThenCheckIsClean(t *testing.T) {
247		html := rawJSONExchange("")
248		html.Target = "/v2/_catalog"
249		html.Status = 404
250		html.RequestHeader = rawHeader("Authorization", rawBasic, "Cookie", "NXSESSIONID=abc123")
251		html.Header = rawHeader(
252			"Server", "Nexus/3.98.1-01 (COMMUNITY)",
253			"Content-Type", "text/html;charset=utf-8",
254			"Set-Cookie", "NXSESSIONID=abc123; Path=/",
255			"X-Foo", "bar",
256		)
257		html.Body = []byte(rawHTML)
258	
259		js := rawJSONExchange("{\n  \"name\" : \"docker-proxy\",\n  \"uploaderIp\" : \"10.1.2.3\",\n  \"url\" : \"http://127.0.0.1:30481/repository/docker-proxy\"\n}")
260		js.Header = rawHeader("Server", "Nexus/3.98.1-01 (COMMUNITY)", "Content-Type", "application/json", "Set-Cookie", "NXSESSIONID=zzz")
261	
262		for name, raw := range map[string]nexusfixture.RawExchange{"html 404": html, "json with uploaderIp": js} {
263			t.Run(name, func(t *testing.T) {
264				base, err := nexusfixture.Parse("c", "synthetic--admin.http", []byte(synthValid))
265				if err != nil {
266					t.Fatal(err)
267				}
268				ex := nexusfixture.Redact(raw)
269				if got := ex.RequestHeader.Get("Authorization"); got != "Basic <redacted>" {
270					t.Errorf("Authorization = %q, want %q", got, "Basic <redacted>")
271				}
272				base.Exchanges = []nexusfixture.Exchange{ex}
273				data := nexusfixture.Format(base)
274				for _, secret := range []string{"dXNlcjpwYXNz", "NXSESSIONID", "10.1.2.3", "datomir", "X-Foo"} {
275					if bytes.Contains(data, []byte(secret)) {
276						t.Errorf("the formatted fixture still holds %q:\n%s", secret, data)
277					}
278				}
279				if leaks := nexusfixture.CheckLeaks("synthetic--admin", data, nil); len(leaks) != 0 {
280					t.Errorf("CheckLeaks on a redacted exchange = %v, want none\n%s", leaks, data)
281				}
282				if _, err := nexusfixture.Parse("c", "synthetic--admin.http", data); err != nil {
283					t.Errorf("the redacted fixture does not parse back: %v\n%s", err, data)
284				}
285			})
286		}
287	}
