18	// denylistEnv names a file, kept OUTSIDE the repository, with one term per
19	// line (names of an instance that must never appear in a fixture).
20	const denylistEnv = "DEVDESK_FIXTURE_DENYLIST"
21	
22	const leakBaseName = "rest-repositories-docker-proxy--admin"
23	
24	// leakBase is the real NX-03 answer the self-tests plant their leaks into: it has
25	// an Authorization line, a Host, a Server header, a JSON body with a URL and the
26	// bench's upstream service. The planted text is invented.
27	func leakBase(t *testing.T) string {
28		t.Helper()
29		fixtures, err := nexusfixture.Load("catalog")
30		if err != nil {
31			t.Fatal(err)
32		}
33		for _, f := range fixtures {
34			if f.Name == leakBaseName {
35				return string(nexusfixture.Format(f))
36			}
37		}
38		t.Fatalf("the catalog campaign has no %s", leakBaseName)
39		return ""
40	}
41	
42	// plant replaces the one occurrence of old in base, failing when the base has
43	// moved and old is no longer there exactly once.
44	func plant(t *testing.T, base, old, repl string) string {
45		t.Helper()
46		if n := strings.Count(base, old); n != 1 {
47			t.Fatalf("the base fixture holds %q %d times, want exactly once", old, n)
48		}
49		return strings.Replace(base, old, repl, 1)
50	}
51	
52	func lineOf(data, needle string) int {
53		i := strings.Index(data, needle)
54		if i < 0 {
55			return 0
56		}
57		return strings.Count(data[:i], "\n") + 1
58	}
