60	const (
61		hdrAuth   = "Authorization: Basic <redacted>\n"
62		hdrHost   = "Host: 127.0.0.1:30481\n"
63		hdrServer = "Server: Nexus/3.98.1-01 (COMMUNITY)\n"
64		bodyOnl   = "  \"online\" : true,\n"
65		bodyURL   = "\"url\" : \"http://127.0.0.1:30481/repository/docker-proxy\""
66		bodyUp    = "\"remoteUrl\" : \"http://bench-upstream.nexus-bench.svc.cluster.local:5000\""
67		metaAcct  = "# account: admin (nx-admin, Basic, sent preemptively)"
68	)
69	
70	// bodyNote adds a JSON member after "online".
71	func bodyNote(member string) (old, repl string) { return bodyOnl, bodyOnl + "  " + member + ",\n" }
72	
73	type leakCase struct {
74		name    string
75		old     string
76		repl    string
77		planted string   // the invented value: it must be found, and never echoed back
78		exact   []string // extra terms handed to CheckLeaks
79	}
80	
81	func leakCases() []leakCase {
82		note := func(name, member, planted string) leakCase {
83			old, repl := bodyNote(member)
84			return leakCase{name: name, old: old, repl: repl, planted: planted}
85		}
86		exactOld, exactRepl := bodyNote(`"note" : "zz-exact-secret-91"`)
87		b64Old, b64Repl := bodyNote(`"note" : "dXNlcjpwYXNzMTIz"`)
88		return []leakCase{
89			// Rule: Authorization other than Basic/Bearer <redacted>.
90			{name: "authorization/basic value", old: hdrAuth, repl: "Authorization: Basic dXNlcjpwYXNzMTIz\n", planted: "dXNlcjpwYXNzMTIz"},
91			{name: "authorization/lowercase name", old: hdrAuth, repl: "authorization: Basic dXNlcjpwYXNzMTIz\n", planted: "dXNlcjpwYXNzMTIz"},
92			{name: "authorization/bearer value", old: hdrAuth, repl: "Authorization: Bearer REDACTED\n", planted: "opaque-token-4242"},
93			{name: "authorization/unknown scheme", old: hdrAuth, repl: "Authorization: Digest response=\"d1g3st-77\"\n", planted: "d1g3st-77"},
94	
95			// Rule: Cookie, Set-Cookie, NXSESSIONID, X-Nexus-UI.
96			{name: "cookie/request Cookie", old: hdrHost, repl: hdrHost + "Cookie: theme=dark; sid=c00kie-val-1\n", planted: "c00kie-val-1"},
97			{name: "cookie/response Set-Cookie", old: hdrServer, repl: hdrServer + "Set-Cookie: sid=sessval-2; Path=/\n", planted: "sessval-2"},
98			{name: "cookie/NXSESSIONID anywhere", old: hdrHost, repl: hdrHost + "X-Trace: NXSESSIONID=zz-nxsess-3\n", planted: "zz-nxsess-3"},
99			{name: "cookie/X-Nexus-UI", old: hdrHost, repl: hdrHost + "X-Nexus-UI: ui-session-9\n", planted: "ui-session-9"},
100	
101			// Rule: a response header outside the allowlist.
102			{name: "allowlist/unknown response header", old: hdrServer, repl: hdrServer + "X-Powered-By: some-proxy-77\n", planted: "some-proxy-77"},
103			{name: "allowlist/Date", old: hdrServer, repl: hdrServer + "Date: Tue, 17 Nov 2026 10:00:00 GMT\n", planted: "Tue, 17 Nov 2026 10:00:00 GMT"},
104	
105			// Rule: a JWT-like value.
106			note("jwt/in a value", `"note" : "eyJhbGciOiJIUzI1NiJ9.zz-payload-5"`, "eyJhbGciOiJIUzI1NiJ9.zz-payload-5"),
107			{name: "jwt/in a header", old: hdrServer, repl: hdrServer + "Link: <eyJhbGciOiJIUzI1NiJ9zz6>; rel=\"next\"\n", planted: "eyJhbGciOiJIUzI1NiJ9zz6"},
108	
109			// Rule: a JSON secret key whose value is not <redacted>.
110			note("json/token", `"token" : "zz-planted-token-1"`, "zz-planted-token-1"),
111			note("json/token compact", `"token":"zz-planted-token-2"`, "zz-planted-token-2"),
112			note("json/access_token", `"access_token" : "zz-planted-access-3"`, "zz-planted-access-3"),
113			note("json/refresh_token", `"refresh_token" : "zz-planted-refresh-4"`, "zz-planted-refresh-4"),
114			note("json/password", `"password" : "zz-planted-password-5"`, "zz-planted-password-5"),
115			note("json/secret", `"secret" : "zz-planted-secret-6"`, "zz-planted-secret-6"),
116			note("json/uploaderIp", `"uploaderIp" : "zz-planted-uploader-7"`, "zz-planted-uploader-7"),
117	
118			// Rule: a host in a URL or Host: outside AllowedHosts.
119			{name: "host/URL in a body", old: bodyURL, repl: "\"url\" : \"http://nexus.zz-corp.example:8081/repository/docker-proxy\"", planted: "nexus.zz-corp.example"},
120			{name: "host/Host header", old: hdrHost, repl: "Host: nexus.zz-corp.example:8081\n", planted: "nexus.zz-corp.example"},
121			{name: "host/public IP", old: bodyURL, repl: "\"url\" : \"http://203.0.113.7:30481/repository/docker-proxy\"", planted: "203.0.113.7"},
122			{name: "host/a namesake of the upstream is not the upstream", old: bodyUp, repl: "\"remoteUrl\" : \"http://bench-upstream.zz-other.svc.cluster.local:5000\"", planted: "zz-other"},
123			{name: "host/https scheme", old: bodyURL, repl: "\"url\" : \"https://nexus.zz-tls.example/repository/docker-proxy\"", planted: "nexus.zz-tls.example"},
