289	// TestRedactLeavesARealAnswerAsItIs: the recorder reads a bench answer, and an
290	// answer that was already clean must come out the same, byte for byte, in the
291	// file (that is what lets it write nothing for an unchanged answer). Stub
292	// fixtures cannot be turned back into a raw body and are left out.
293	func TestRedactLeavesARealAnswerAsItIs(t *testing.T) {
294		all, err := nexusfixture.All()
295		if err != nil {
296			t.Fatal(err)
297		}
298		checked := 0
299		for _, f := range all {
300			for i, ex := range f.Exchanges {
301				if ex.Stub != "" {
302					continue
303				}
304				checked++
305				raw := nexusfixture.RawExchange{
306					Method: ex.Method, Target: ex.Target, Host: ex.Host,
307					RequestHeader: ex.RequestHeader.Clone(), Status: ex.Status,
308					Header: ex.Header.Clone(), Body: slices.Clone(ex.Body),
309				}
310				got := nexusfixture.Redact(raw)
311				got.Reason, ex.Reason = "", "" // the raw answer has none: Format falls back to the standard phrase
312	
313				want, have := f, f
314				want.Exchanges, have.Exchanges = []nexusfixture.Exchange{ex}, []nexusfixture.Exchange{got}
315				if w, h := nexusfixture.Format(want), nexusfixture.Format(have); !bytes.Equal(w, h) {
316					t.Errorf("%s exchange %d: Redact changed a clean answer\nwant:\n%s\ngot:\n%s", f.Name, i+1, w, h)
317				}
318			}
319		}
320		if checked == 0 {
321			t.Fatal("no verbatim exchange was checked: the test is vacuous")
322		}
323	}
