199	func TestCheckLeaksEachRuleCatchesItsLeak(t *testing.T) {
200		base := leakBase(t)
201		if leaks := nexusfixture.CheckLeaks(leakBaseName, []byte(base), nil); len(leaks) != 0 {
202			t.Fatalf("the unmodified base is not clean (%v): every case below would be meaningless", leaks)
203		}
204	
205		rules := map[string]bool{}
206		for _, tc := range leakCases() {
207			t.Run(tc.name, func(t *testing.T) {
208				data := plant(t, base, tc.old, tc.repl)
209				line := lineOf(data, tc.planted)
210				if line == 0 {
211					t.Fatalf("the planted value %q is not in the fixture: the case is broken", tc.planted)
212				}
213				leaks := nexusfixture.CheckLeaks("planted--admin", []byte(data), tc.exact)
214				if len(leaks) == 0 {
215					t.Fatalf("no leak reported for a planted %s:\n%s", tc.name, data)
216				}
217				for _, l := range leaks {
218					if l.Fixture != "planted--admin" {
219						t.Errorf("Leak.Fixture = %q, want the name given to CheckLeaks", l.Fixture)
220					}
221					if l.Rule == "" {
222						t.Errorf("a leak at line %d has no Rule", l.Line)
223					}
224					if l.Line != line {
225						t.Errorf("leak %q reported at line %d, want line %d (the only line that changed)", l.Rule, l.Line, line)
226					}
227					rules[l.Rule] = true
228				}
229				if echoed := fmt.Sprintf("%+v %#v", leaks, leaks); strings.Contains(echoed, tc.planted) {
230					t.Errorf("the leaks repeat the planted value: %s", echoed)
231				}
232			})
233		}
234		// The plan names nine rules (authorization, cookie/session, allowlist, JWT,
235		// JSON secret, host, private address, internal name, exact term): the cases
236		// above must not all be reported under fewer names.
237		if len(rules) < 9 {
238			t.Errorf("the planted leaks were reported under %d distinct Rule names (%v), want at least 9", len(rules), rules)
239		}
240	}
