297	// TestEmbeddedFixturesLeakNothing is the guard of criterion 1: every committed
298	// fixture, byte for byte as it sits in the tree, passes the leak check.
299	func TestEmbeddedFixturesLeakNothing(t *testing.T) {
300		all, err := nexusfixture.All()
301		if err != nil {
302			t.Fatal(err)
303		}
304		files, err := filepath.Glob(filepath.Join("fixtures", "*", "*.http"))
305		if err != nil {
306			t.Fatal(err)
307		}
308		if len(files) == 0 || len(files) != len(all) {
309			t.Fatalf("%d fixture files on disk, %d embedded: the scan would not cover what the tests replay", len(files), len(all))
310		}
311	
312		exact := externalDenylist(t)
313		for _, file := range files {
314			data, err := os.ReadFile(file)
315			if err != nil {
316				t.Fatal(err)
317			}
318			name := strings.TrimSuffix(filepath.Base(file), ".http")
319			for _, l := range nexusfixture.CheckLeaks(name, data, exact) {
320				t.Errorf("%s line %d: leak, rule %q", file, l.Line, l.Rule)
321			}
322		}
323	
324		// The same files, as parsed and written back, say the same: Format is what
325		// the recorder writes.
326		for _, f := range all {
327			for _, l := range nexusfixture.CheckLeaks(f.Name, nexusfixture.Format(f), exact) {
328				t.Errorf("%s (formatted) line %d: leak, rule %q", f.Name, l.Line, l.Rule)
329			}
330		}
